#include <vector>
#include <cstddef>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) {
        return;
    }

    std::vector<double> blockSums;
    std::vector<double> blockOffsets;

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        #pragma omp single
        {
            blockSums.assign(static_cast<std::size_t>(nt), 0.0);
            blockOffsets.assign(static_cast<std::size_t>(nt), 0.0);
        }

        const std::size_t start =
            (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end =
            (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        // Local inclusive scan for this thread's chunk.
        double running = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            running += x[i];
            output[i] = running;
        }

        // One unique element per thread: no race.
        blockSums[static_cast<std::size_t>(tid)] = running;

        // Ensure all block sums are available before computing offsets.
        #pragma omp barrier

        // Compute per-block offsets once.
        #pragma omp single
        {
            double offset = 0.0;
            for (int t = 0; t < nt; ++t) {
                blockOffsets[static_cast<std::size_t>(t)] = offset;
                offset += blockSums[static_cast<std::size_t>(t)];
            }
        }

        // Apply this thread's block offset to its chunk.
        const double offset = blockOffsets[static_cast<std::size_t>(tid)];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
